    beats = {
        { id = "nest", at = 15, title = "The nest",
            text = "I was born under a garden shed, in a nest of dry leaves, one of five. Our spines were white and soft at first. My mother said they would harden. She said the same about me in general. I am still waiting." },
        { id = "roll", at = 40, title = "The first roll",
            text = "The first time I rolled up, a leaf had fallen on me. Only a leaf. My brothers laughed for a whole night. I stayed rolled until morning, to be sure about the leaf." },
        { id = "setting_out", at = 80, title = "Setting out",
            text = "Hedgehogs leave home young, and alone. One evening my mother touched noses with each of us and walked off into the grass. I waited a while, in case she had forgotten something. Then I chose a direction." },
        { id = "fence", at = 140, title = "The long fence",
            text = "My first summer I met a fence with no end. Smooth boards, no gap, and on the far side the smell of beetles and wet moss. I walked along that fence for nine nights. I tell you this so you know I can be stubborn." },
        { id = "gap", at = 220, title = "The door",
            text = "On the tenth night there was a hole in the fence. Square, neat, just my size, with a saucer of water beside. Somebody had made a door for a hedgehog. I never saw who. I think about them most evenings." },
        { id = "road", at = 320, title = "The road",
            text = "Beyond the gardens there was a road. Lights came along very fast, with a roaring. I waited on the verge for a quiet I could trust. Then I ran. I have never been so quick, and I hope never to need to be again." },
        { id = "winter", at = 450, title = "The first winter",
            text = "Nobody tells you how to sleep for a winter. I built a nest of leaves under a bramble and lay down, and my heart went slow. I was afraid of one thing: waking in spring to find nobody had kept anything for me." },
        { id = "waking", at = 600, title = "Waking",
            text = "I woke in March, thin as a twig, to the smell of rain. Everything was still there. The bramble, the beetles, the moon. I cried a little, which for a hedgehog is mostly sniffing. Then I ate for a week." },
        { id = "doors", at = 800, title = "More doors",
            text = "After that I began to find more gaps. One under a gate. One in a wall, with a small ramp. Garden after garden, somebody had been leaving doors open for me. I followed them the way you follow a story." },
        { id = "garden", at = 1050, title = "The last door",
            text = "The last gap opened into this garden. There was a dry place under the hedge, and a person sitting very still with a book. I had never seen someone so large be so quiet. I thought: here. I will be brave here." },
        { id = "still", at = 1400, title = "Two kinds of still",
            text = "When you read, your breathing goes slow, like mine in winter. I lie close and listen, {total} pages now. I used to think stillness was only for hiding. You showed me another kind, the kind you choose." },
        { id = "soft", at = 1800, title = "The soft place",
            text = "I have six thousand ways to say keep away and one soft place, and you know where that is. I used to fear the long sleep, in case nothing waited on the other side. I am not afraid now. You will be here, reading. I will wake, and unroll, and say hello." },
    },
